[
  {
    "alert_id": "DTG_WEIGHT_GAIN_001",
    "title": "DTG-associated weight gain with obesity and metabolic risk",
    "message": "Guidelines state clinicians should discuss weight gain when starting all ART regimens and proactively advise on diet and exercise, as obesity is an increasing problem particularly among women. Patient gained 17kg (65→82kg) and BMI rose from 25.6 to 32.4 within 18 months of switching to DTG. She now has acanthosis nigricans, BP elevated from 118/74 to 138/88, fasting glucose risen from 92 to 118 mg/dL, HbA1c 6.1%, and dyslipidaemia. DTG is strongly associated with weight gain, especially after switch from EFV. Non-drug factors (family history of diabetes, dietary changes) may also contribute. The compounding of obesity, pre-diabetes, hypertension, and dyslipidaemia substantially increases cardiovascular risk.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Provide structured diet and exercise counselling. Consider weight-loss therapy such as GLP-1 agonists if affordable. Evaluate for alternative ART if weight gain continues despite lifestyle intervention.",
    "citations": [
      {"page_number": 8, "chunk_id": "sahcs_adult_art_2024__sahcs_adult_art_2024__p8_c4"}
    ]
  },
  {
    "alert_id": "DTG_GLUCOSE_MONITORING_002",
    "title": "Missing glucose monitoring plan for DTG patient",
    "message": "Guidelines specify glucose monitoring every 3 months for the first year when initiating or transitioning to DTG. Patient transitioned to DTG 18 months ago and now has impaired fasting glucose (118 mg/dL) and HbA1c 6.1% (pre-diabetic range). No glucose monitoring appears to have been performed between baseline and today's visit, and the clinician's plan contains no orders for ongoing glucose monitoring or diabetes screening. This is a significant monitoring gap given the patient's family history of type 2 diabetes, acanthosis nigricans, and new-onset obesity.",
    "issue_type": "monitoring_gap",
    "severity": "high",
    "recommended_action": "Initiate glucose monitoring every 3 months. Refer for formal diabetes screening and dietary intervention given pre-diabetic HbA1c and family history.",
    "citations": [
      {"page_number": 5, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p5_c3"}
    ]
  },
  {
    "alert_id": "METABOLIC_WORKUP_GAP_003",
    "title": "No clinician plan despite multiple metabolic abnormalities",
    "message": "Patient presents with new-onset impaired fasting glucose, pre-diabetic HbA1c, dyslipidaemia (LDL 148, HDL 38, triglycerides 212), elevated BP (138/88), BMI 32.4, and acanthosis nigricans. The clinician's assessment and plan section is blank with no orders, medicine changes, or follow-up documented. These abnormalities collectively signal metabolic syndrome and warrant urgent clinical action. Guidelines emphasise proactive management of weight gain and its metabolic consequences in patients on DTG-based regimens.",
    "issue_type": "plan_review",
    "severity": "high",
    "recommended_action": "Document assessment and plan addressing weight, glucose, lipids, and BP. Order repeat fasting glucose, lipid panel, and BP follow-up. Consider lifestyle and pharmacologic intervention.",
    "citations": [
      {"page_number": 8, "chunk_id": "sahcs_adult_art_2024__sahcs_adult_art_2024__p8_c4"}
    ]
  }
]

